static inline o_Lexer* orbit_model_o_Lexer_create(OrbitArena* arena_, orbit_string source, orbit_int sourceLen, orbit_int pos, orbit_int line, orbit_int col) {
    o_Lexer* m = (o_Lexer*)orbit_alloc(arena_, sizeof(o_Lexer));
    m->source = source;
    m->sourceLen = sourceLen;
    m->pos = pos;
    m->line = line;
    m->col = col;
    return m;
}

